import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';

const Profile = ({ currentUser }) => {
  const { username } = useParams();
  const [profile, setProfile] = useState(null);

  useEffect(() => {
    const fetchProfile = async () => {
      try {
        const res = await axios.get(`/users/${username}`);
        setProfile(res.data);
      } catch (err) { console.error(err); }
    };
    fetchProfile();
  }, [username]);

  if (!profile) return <p style={{ textAlign: 'center', marginTop: '50px' }}>Loading profile...</p>;
  const isMe = profile.user.username === currentUser.username;

  return (
    <div style={{ maxWidth: '900px', margin: '40px auto', padding: '0 20px' }}>
      <div style={{ display: 'flex', marginBottom: '40px', padding: '20px', alignItems: 'center' }}>
        <div style={{ width: '150px', height: '150px', borderRadius: '50%', background: '#efefef', marginRight: '50px', border: '2px solid #dbdbdb' }}></div>
        <div>
          <h2 style={{ marginBottom: '20px', fontWeight: '400' }}>{profile.user.username}</h2>
          <div style={{ display: 'flex', gap: '30px', marginBottom: '20px' }}>
            <p><strong>{profile.posts.length}</strong> posts</p>
            <p><strong>{profile.user.followers.length}</strong> followers</p>
            <p><strong>{profile.user.following.length}</strong> following</p>
          </div>
          <p style={{ fontWeight: '600' }}>{profile.user.bio}</p>
        </div>
      </div>
      <div style={{ borderTop: '1px solid #dbdbdb', paddingTop: '20px' }}>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '10px' }}>
          {profile.posts.map(post => (
            <div key={post._id} style={{ position: 'relative', aspectRatio: '1', overflow: 'hidden', borderRadius: '4px' }}>
              <img src={`http://localhost:5000/${post.image}`} alt="post" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Profile;
